  state: Game.state,
  map: Overworld.player.map, x: Overworld.player.x, y: Overworld.player.y,
  party: Game.save.party.map(m => ({ id: m.id, lv: m.level, hp: m.hp })),
  flags: Game.save.flags,
  battle: Battle.active(),
  uiBusy: UI.busy(),
}));

await page.goto('http://localhost:8741/');
await new Promise(r => setTimeout(r, 1500));
await shot('01-title');

// New game
